// === Tab: mySketch ===
function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
}

function draw() {
	background(0);
	let d = millis() / 10;
	rotateY(d * 0.004);
   randomSeed(0);
	let r = 140,
		p = 10; 
	let x, y, z;
	for (let j = 0; j < 500; j++) {
      x = (randomGaussian() + sin(d / 203)) * 200;
      y = (randomGaussian() + sin(d / 197)) * 200;
      z = randomGaussian() * 200;
      stroke(random(255));
      push();
      translate(x, y, z);
      sphere(random(0.05));
      pop();
    }
    for (let j = 0; j < 1000; j++) {
      x = random(-r, r);
      y = random(-r, r);
      z = random(-r, r);
      if (abs(x) < r - p && abs(y) < r - p && abs(z) < r - p) continue;
      let c = [
        color(random(255), random(255), 255),
        color(255, random(255), random(255)),
        color(random(255), 255, random(255)),
      ];
	 let s = sin(d / 150);
    if (s >= 0) stroke(lerpColor(c[1], c[0], s));
    else stroke(lerpColor(c[1], c[2], -s));
    push();
    translate(x, y, z);
    sphere(random(1.5));
    pop();
    }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

